Also, `--cpu-prof-interval` is listed in `bun --help` and works (on `idle.js`, about 130 samples at
1000 µs and 14 at 10000 µs), but the CPU profiling flag table in `docs/project/benchmarking.mdx`
does not list it.

### What version of Bun is running?

1.4.2+744846f84

### What platform is your computer?

Darwin 27.0.0 arm64 arm (macOS 27.0, build 26A428)

### What steps can reproduce the bug?

Follow-up to #40573. The `kDNSServiceAttrAllowFailover` change from #40675 does not fix this on my machine, and I think I've found why.

Setup: a corporate VPN pushes split DNS for `corp.example`. iCloud Private Relay is active, so mDNSResponder's first-choice DNS service for most queries is ODoH. `scutil --dns` (sanitized):

```
resolver #1
  nameserver[0] : 2001:db8::1
  nameserver[1] : 192.168.1.1
  if_index : 7 (en0)
  flags    : Request A records, Request AAAA records

resolver #2
  domain   : corp.example
  nameserver[0] : fd00::53
  nameserver[1] : 10.0.0.53
  flags    : Supplemental, Request A records, Request AAAA records
  reach    : 0x00000002 (Reachable)
```

```js
const h = "host.corp.example";
for (const backend of [undefined, "system", "libc", "c-ares"]) {
  try { console.log(backend, JSON.stringify(await Bun.dns.lookup(h, { backend }))); }
  catch (e) { console.log(backend, "ERR", e.code); }
}
try { console.log("fetch", (await fetch(`https://${h}/`, { method: "HEAD" })).status); }
catch (e) { console.log("fetch ERR", e.code); }
```

### What is the expected behavior?

Same result as libc `getaddrinfo` (`dscacheutil -q host -a name host.corp.example`, curl, Python and Node all resolve it):

```
libc [{"address":"fd00::10","family":6,"ttl":0},{"address":"10.0.0.10","family":4,"ttl":0}]
```

### What do you see instead?

```
undefined ERR DNS_ENOTFOUND
system ERR DNS_ENOTFOUND
libc [{"address":"fd00::10","family":6,"ttl":0},{"address":"10.0.0.10","family":4,"ttl":0}]
c-ares ERR DNS_ENOTFOUND
fetch ERR ENOTFOUND
```

Unlike #40573 (1.4.0), `fetch()` is affected too, because the connect path also goes through `dns_sd` now. `BUN_FEATURE_FLAG_DISABLE_DNS_CACHE_LIBINFO=1` fixes `fetch()` (it then gets as far as TLS) but not `dns.lookup()`. Public names resolve fine.

### Additional information

#### Root cause: `DNSServiceGetAddrInfoEx` + `kDNSServiceAttrAllowFailover` never fails over

libinfo's `getaddrinfo` does not call `DNSServiceGetAddrInfo(Ex)`. On this macOS, `libsystem_info.dylib` imports only `DNSServiceQueryRecordWithAttribute` + `kDNSServiceAttrAllowFailover` from dnssd:

```
$ dyld_info -imports /usr/lib/system/libsystem_info.dylib | grep -i dnsservice
      _DNSServiceCreateConnection  (from libsystem_dnssd)
      _DNSServiceProcessResult  (from libsystem_dnssd)
      _DNSServiceQueryRecordWithAttribute  (from libsystem_dnssd)
      _DNSServiceRefDeallocate  (from libsystem_dnssd)
      _DNSServiceRefSockFD  (from libsystem_dnssd)
      _kDNSServiceAttrAllowFailover  (from libsystem_dnssd)
```

It issues one query per record type (A and AAAA). mDNSResponder honors the failover attribute for those queries, but not for `DNSServiceGetAddrInfoEx` with the same attribute, which is what `src/runtime/dns_jsc/dns_sd.rs` uses.

Standalone reproducer, no Bun involved. It uses the same base flags as `dns_sd.rs` (Timeout | ReturnIntermediates | SuppressUnusable):

<details><summary>sdrepro.c</summary>

```c
// cc -Wno-deprecated-declarations -o sdrepro sdrepro.c && ./sdrepro host.corp.example
#include <arpa/inet.h>
#include <dlfcn.h>
#include <dns_sd.h>
#include <netdb.h>
#include <stdio.h>
#include <sys/select.h>

typedef DNSServiceErrorType (*GaiExFn)(DNSServiceRef *, DNSServiceFlags, uint32_t, DNSServiceProtocol,
                                       const char *, const void *, DNSServiceGetAddrInfoReply, void *);
typedef DNSServiceErrorType (*QrAttrFn)(DNSServiceRef *, DNSServiceFlags, uint32_t, const char *, uint16_t,
                                        uint16_t, const void *, DNSServiceQueryRecordReply, void *);

// Same base flags Bun 1.4.2 uses (minus ShareConnection, irrelevant here).
#define BASE_FLAGS (kDNSServiceFlagsTimeout | kDNSServiceFlagsReturnIntermediates | kDNSServiceFlagsSuppressUnusable)

static int done;

static void gai_reply(DNSServiceRef r, DNSServiceFlags f, uint32_t ifi, DNSServiceErrorType e, const char *h,
                      const struct sockaddr *a, uint32_t ttl, void *ctx) {
  char buf[64] = "-";
  if (a && a->sa_family == AF_INET) inet_ntop(AF_INET, &((struct sockaddr_in *)a)->sin_addr, buf, sizeof buf);
  if (a && a->sa_family == AF_INET6) inet_ntop(AF_INET6, &((struct sockaddr_in6 *)a)->sin6_addr, buf, sizeof buf);
  printf("    err=%d flags=0x%x %s ttl=%u\n", e, f, buf, ttl);
  if (!(f & kDNSServiceFlagsMoreComing)) done++;
}

static void qr_reply(DNSServiceRef r, DNSServiceFlags f, uint32_t ifi, DNSServiceErrorType e, const char *name,
                     uint16_t type, uint16_t cls, uint16_t len, const void *rd, uint32_t ttl, void *ctx) {
  char buf[64] = "-";
  if (e == 0 && type == kDNSServiceType_A && len == 4) inet_ntop(AF_INET, rd, buf, sizeof buf);
  if (e == 0 && type == kDNSServiceType_AAAA && len == 16) inet_ntop(AF_INET6, rd, buf, sizeof buf);
  printf("    type=%u err=%d flags=0x%x %s ttl=%u\n", type, e, f, buf, ttl);
  if (!(f & kDNSServiceFlagsMoreComing)) done++;
}

static void drain(DNSServiceRef *refp, DNSServiceErrorType err, int want) {
  DNSServiceRef ref = *refp;
  done = 0;
  while (err == 0 && done < want) {
    int fd = DNSServiceRefSockFD(ref);
    fd_set s;
    FD_ZERO(&s);
    FD_SET(fd, &s);
    struct timeval tv = {5, 0};
    if (select(fd + 1, &s, NULL, NULL, &tv) <= 0 || DNSServiceProcessResult(ref) != 0) break;
  }
  if (ref) DNSServiceRefDeallocate(ref);
}

int main(int argc, char **argv) {
  setvbuf(stdout, NULL, _IONBF, 0);
  const char *host = argc > 1 ? argv[1] : "host.corp.example";
  const DNSServiceProtocol both = kDNSServiceProtocol_IPv4 | kDNSServiceProtocol_IPv6;
  GaiExFn gai_ex = (GaiExFn)dlsym(RTLD_DEFAULT, "DNSServiceGetAddrInfoEx");
  QrAttrFn qr_attr = (QrAttrFn)dlsym(RTLD_DEFAULT, "DNSServiceQueryRecordWithAttribute");
  const void *failover = dlsym(RTLD_DEFAULT, "kDNSServiceAttrAllowFailover");
