4jJ6Wfn2KchwlKCLsiEyeg4RhMD+FGv8ZA==
-----END EC PRIVATE KEY-----`;
const CERT = `-----BEGIN CERTIFICATE-----
MIH/MIGmAgEBMAoGCCqGSM49BAMCMAwxCjAIBgNVBAMMAXgwHhcNMjQwMTAxMDAw
MDAwWhcNNDkxMjMxMjM1OTU5WjAMMQowCAYDVQQDDAF4MFkwEwYHKoZIzj0CAQYI
KoZIzj0DAQcDQgAEtTIIdTHzuEHCTGZteRNcMR2N3vUjM9BqEdB6kCb0PcZ+1QQy
R3/J4jJ6Wfn2KchwlKCLsiEyeg4RhMD+FGv8ZDAKBggqhkjOPQQDAgNIADBFAiBP
