-----END CERTIFICATE-----`;

let stuck = false; // duplex a's backpressure switch
let got = 0; // plaintext bytes received by the client
let sent = 0; // ciphertext bytes delivered through duplex a
const q = []; // a's backlog: [chunk, writeCallback] pairs

// In-memory wire: writes on either duplex are pushed to the other's reader.
const b = new Duplex({ read() {}, write(c, _, cb) { a.push(c); cb(); } });
const a = new Duplex({
  read() {},
  write(c, _, cb) {
    if (stuck) q.push([c, cb]);
    else { sent += c.length; b.push(c); cb(); }
