    console.log(`end() callback fired: client has ${got}/1 bytes, ${sent} ciphertext bytes delivered`);
    console.log(
      ok
        ? "PASS: callback waited for the backpressured backlog to flush"
        : "FAIL: callback fired while the backlog was still unflushed",
    );
    process.exit(ok ? 0 : 1);
  });
  setTimeout(() => {
    // Resume the wrapped stream — in node this is what finally lets end(cb) run.
    stuck = false;
    for (const [c, cb] of q.splice(0)) { sent += c.length; b.push(c); cb(); }
  }, 100);
});
client.on("data", (d) => (got += d.length));
client.on("error", (e) => { console.log(`[client] ${e.message}`); process.exit(1); });

